    static final int INK=Color.rgb(19,35,30),MUTED=Color.rgb(107,124,115),PAPER=Color.rgb(246,248,243),GREEN=Color.rgb(24,111,75),LIME=Color.rgb(197,235,91),WHITE=Color.WHITE;
    LinearLayout root,body; String page="Live",role="Scorer"; Store store; Match match; int pendingRuns=0; String pendingExtra="NONE"; boolean pendingWicket=false;
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);store=new Store(this);match=store.active();draw();}
    TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
    Button btn(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(12);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?WHITE:INK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(primary?GREEN:Color.rgb(236,241,232)));return b;}
    void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(PAPER);setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(18),dp(9),dp(18),dp(9));TextView brand=text("BOUNDARY  /  CLUB CRICKET",11,GREEN,true);header.addView(brand,new LinearLayout.LayoutParams(0,dp(38),1));Button rb=btn(role+" ▾",false);rb.setOnClickListener(v->chooseRole());header.addView(rb);root.addView(header);ScrollView sv=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(18),dp(8),dp(18),dp(20));sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(WHITE);String[] tabs={"Live","Tournaments","Teams","Insights"};for(String t:tabs){Button b=btn(t.equals(page)?t+" •":t,t.equals(page));b.setTextSize(10);nav.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{page=t;draw();});}root.addView(nav);switch(page){case "Live":live();break;case "Tournaments":tournaments();break;case "Teams":teams();break;default:insights();}}
